WITH unpacked AS (SELECT id, created_at, items, AGGREGATE(items, CAST(0 AS DOUBLE), (acc, x) -> acc + x.qty * x.price, acc -> ROUND(acc, 2)) AS items_total, attributes['gift'] AS gift, attributes['device'] AS device FROM carts WHERE TO_DATE(created_at) >= '2025-03-01') SELECT id, created_at, items_total, gift, COUNT(items_total) OVER w_ordered AS running_count_items_total, SUM(items_total) OVER w_ordered AS running_sum_items_total, AVG(items_total) OVER w_ordered AS running_avg_items_total, MAX(items_total) OVER w_ordered AS running_max_items_total FROM unpacked WHERE items_total < 800 WINDOW w_ordered AS (ORDER BY items_total, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
